/* cobertura Dropi: 'C' contra entrega · 'A' solo pago anticipado · 'N' no hay envío (la usa el formulario al pulsar Pedir) */
window.cobDropiMX = (function () {
  var C = null, A = null;
  var sinAc = function (s) { return String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z ]/g, ' ').replace(/\s+/g, ' ').trim(); };
  var aSet = function (s) { var o = {}; for (var i = 0; i < s.length; i += 5) o[s.substr(i, 5)] = 1; return o; };
  return function (est, muni, cp) {
    if (!C) { C = aSet(window.CP_C_MX || ''); A = aSet(window.CP_A_MX || ''); }
    cp = String(cp || '').replace(/\D/g, '');
    if (/^\d{5}$/.test(cp)) { if (C[cp]) return 'C'; if (A[cp]) return 'A'; }
    var lista = (window.MUNICIPIOS_MX || {})[est] || [];
    if (lista.indexOf(muni) < 0) return 'N';
    if (/^\d{5}$/.test(cp)) { var p = (window.PREF_MX || {})[sinAc(muni)] || '', zona = false;
      for (var i = 0; i < p.length; i += 3) if (p.substr(i, 3) === cp.slice(0, 3)) zona = true;
      if (!zona) return 'N'; }
    return ((window.SOLO_ANTICIPADO_MX || {})[est] || []).indexOf(muni) >= 0 ? 'A' : 'C';
  };
})();

